var stateRoot = System.IO.Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.LocalApplicationData), "PSFlowBridge");
var script = System.Text.Encoding.UTF8.GetString(System.Convert.FromBase64String(""));
var expectedScript = "110cba42657dc2cb3e33f7f8556daf9b209a3a52d3e47748c6a21b296fd943eb";
var installerDir = System.IO.Path.Combine(stateRoot,"installers",expectedScript.Substring(0,16));
System.IO.Directory.CreateDirectory(installerDir);
var installer = System.IO.Path.Combine(installerDir,"Install.ps1");
System.Func<string,string> hash = file => {
    using(var algorithm=System.Security.Cryptography.SHA256.Create())
    using(var stream=System.IO.File.OpenRead(file))
        return System.BitConverter.ToString(algorithm.ComputeHash(stream)).Replace("-","").ToLowerInvariant();
};
using(var mutex=new System.Threading.Mutex(false,"Local\\PSFlowBridgeInstallerSource")) {
    var acquired=false;
    try {
        try{acquired=mutex.WaitOne(10000);}catch(System.Threading.AbandonedMutexException){acquired=true;}
        if(!acquired)throw new System.Exception("运行入口正在准备，请稍后重开。");
        if(!System.IO.File.Exists(installer)||hash(installer)!=expectedScript) {
            var temporary=installer+"."+System.Guid.NewGuid().ToString("N")+".tmp";
            try {
                System.IO.File.WriteAllText(temporary,script,new System.Text.UTF8Encoding(false));
                if(hash(temporary)!=expectedScript)throw new System.Exception("安装入口校验失败，未启动。");
                if(System.IO.File.Exists(installer))System.IO.File.Replace(temporary,installer,null);
                else System.IO.File.Move(temporary,installer);
            } finally {if(System.IO.File.Exists(temporary))System.IO.File.Delete(temporary);}
        }
    } finally {if(acquired)mutex.ReleaseMutex();}
}
var operation="";
try { operation=context.GetVarValue<string>("op","")??""; } catch { }
if(string.IsNullOrEmpty(operation)){try{operation=context.GetVarValue<string>("maintenance","")??"";}catch{}}
if(operation=="install")operation="";
var validOps=new System.Collections.Generic.HashSet<string>{
    "","inspect","install-local","repair-runtime","rollback-app","clear-cache","remove-local","uninstall-runtime","delete-user-data","remove-components"
};
if(!validOps.Contains(operation))throw new System.Exception("维护操作无效："+operation);
var installMode="";
try { installMode=context.GetVarValue<string>("installMode","")??""; } catch { }
if(string.IsNullOrEmpty(installMode)){try{installMode=context.GetVarValue<string>("mode","")??"";}catch{}}
if(installMode!=""&&installMode!="browser"&&installMode!="local")throw new System.Exception("运行方式无效。");
var expectedBuildId="";
try { expectedBuildId=context.GetVarValue<string>("expectedBuildId","")??""; } catch { }
var requestId="";
try { requestId=context.GetVarValue<string>("requestId","")??""; } catch { }
var confirmDelete=false;
try { confirmDelete=context.GetVarValue<bool>("confirmDeleteData",false); } catch { }
var statusFile=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"psfb-distribution-"+System.Guid.NewGuid().ToString("N")+".json");
var outerProgressFile=System.Environment.GetEnvironmentVariable("PSFB_INSTALL_PROGRESS_FILE");
var progressFile=!string.IsNullOrEmpty(outerProgressFile)?outerProgressFile:System.IO.Path.Combine(System.IO.Path.GetTempPath(),"psfb-install-progress-"+System.Guid.NewGuid().ToString("N")+".json");
var isProgressOwner=string.IsNullOrEmpty(outerProgressFile) && (operation==""||operation=="install-local"||operation=="repair-runtime"||operation=="rollback-app");
context.SetVarValue("installRunning",false);
context.SetVarValue("installDone",false);
var initProgress = new Newtonsoft.Json.Linq.JObject();
initProgress["phase"] = "prepare";
initProgress["detail"] = "正在准备运行环境";
initProgress["percent"] = 0;
context.SetVarValue("installProgress",initProgress.ToString(Newtonsoft.Json.Formatting.None));
System.Windows.Window progressWin = null;
System.Windows.Threading.Dispatcher progressDispatcher = null;
System.Windows.Controls.ProgressBar pBar = null;
System.Windows.Controls.TextBlock pMsg = null;
System.Windows.Controls.TextBlock pPct = null;
System.Threading.Thread progressUiThread = null;
bool progressFinished = false;
if (isProgressOwner) {
    var readyEvt = new System.Threading.ManualResetEventSlim(false);
    progressUiThread = new System.Threading.Thread(() => {
        try {
            if (progressFinished) { readyEvt.Set(); return; }
            var w = new System.Windows.Window {
                Title = "PS Flow · 安装进度",
                Width = 360,
                Height = 220,
                WindowStartupLocation = System.Windows.WindowStartupLocation.CenterScreen,
                ResizeMode = System.Windows.ResizeMode.NoResize,
                Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(38, 40, 43)),
                ShowActivated = false,
                Visibility = System.Windows.Visibility.Hidden
            };
            var stack = new System.Windows.Controls.StackPanel { Margin = new System.Windows.Thickness(24, 22, 24, 22) };
            var title = new System.Windows.Controls.TextBlock {
                Text = "PS Flow 正在准备运行组件",
                FontSize = 14,
                FontWeight = System.Windows.FontWeights.SemiBold,
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(230, 230, 230)),
                Margin = new System.Windows.Thickness(0, 0, 0, 14)
            };
            pBar = new System.Windows.Controls.ProgressBar {
                Height = 8,
                IsIndeterminate = true,
                Background = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(58, 61, 66)),
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(91, 157, 255))
            };
            var row = new System.Windows.Controls.Grid { Margin = new System.Windows.Thickness(0, 10, 0, 0) };
            row.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
            row.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = System.Windows.GridLength.Auto });
            pMsg = new System.Windows.Controls.TextBlock {
                Text = "正在准备…",
                FontSize = 12,
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(154, 160, 166)),
                TextTrimming = System.Windows.TextTrimming.CharacterEllipsis
            };
            pPct = new System.Windows.Controls.TextBlock {
                Text = "",
                FontSize = 12,
                Foreground = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(200, 204, 208)),
                Margin = new System.Windows.Thickness(10, 0, 0, 0)
            };
            System.Windows.Controls.Grid.SetColumn(pMsg, 0);
            System.Windows.Controls.Grid.SetColumn(pPct, 1);
            row.Children.Add(pMsg);
            row.Children.Add(pPct);
            stack.Children.Add(title);
            stack.Children.Add(pBar);
            stack.Children.Add(row);
            w.Content = stack;
            progressWin = w;
            progressDispatcher = w.Dispatcher;
            readyEvt.Set();
            if (progressFinished) {
                try { w.Close(); } catch { }
                return;
            }
            System.Windows.Threading.Dispatcher.Run();
        } catch { readyEvt.Set(); }
    });
    progressUiThread.SetApartmentState(System.Threading.ApartmentState.STA);
    progressUiThread.IsBackground = true;
    progressUiThread.Start();
    readyEvt.Wait(1000);
}
try {
    var start=new System.Diagnostics.ProcessStartInfo {
        FileName=System.IO.Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.Windows),"System32","WindowsPowerShell","v1.0","powershell.exe"),
        Arguments="-NoProfile -ExecutionPolicy Bypass -File \""+installer+"\""+
            (operation.Length>0?" -Maintenance \""+operation+"\"":"")+
            (installMode.Length>0?" -Mode \""+installMode+"\"":"")+
            (expectedBuildId.Length>0?" -ExpectedBuildId \""+expectedBuildId+"\"":"")+
            (requestId.Length>0?" -RequestId \""+requestId+"\"":"")+
            (confirmDelete?" -ConfirmDeleteData":""),
        UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,
        RedirectStandardOutput=true,RedirectStandardError=true
    };
    start.EnvironmentVariables["PSFB_INSTALL_STATUS_FILE"]=statusFile;
    start.EnvironmentVariables["PSFB_INSTALL_PROGRESS_FILE"]=progressFile;
    var effectiveOp = (string.IsNullOrEmpty(operation) || operation == "install") ? "install" : operation;
    System.DateTime initialOuterFileTime = System.DateTime.MinValue;
    bool initialOuterFileExisted = false;
    if (!isProgressOwner && System.IO.File.Exists(progressFile)) {
        initialOuterFileExisted = true;
        initialOuterFileTime = System.IO.File.GetLastWriteTimeUtc(progressFile);
    }
    context.SetVarValue("installRunning",true);
    using(var process=System.Diagnostics.Process.Start(start)) {
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();
        var deadline=System.DateTime.UtcNow.AddSeconds(600);
        var startTime=System.DateTime.UtcNow;
        bool windowShown = false;
        while(!process.WaitForExit(700)) {
            try {
                if(System.IO.File.Exists(progressFile)) {
                    if (initialOuterFileExisted && System.IO.File.GetLastWriteTimeUtc(progressFile) == initialOuterFileTime) {
                        // stale external progress file from before this launch
                    } else {
                        initialOuterFileExisted = false;
                        string ptext = null;
                        try {
                            using (var fs = new System.IO.FileStream(progressFile, System.IO.FileMode.Open, System.IO.FileAccess.Read, System.IO.FileShare.ReadWrite))
                            using (var sr = new System.IO.StreamReader(fs, System.Text.Encoding.UTF8)) {
                                ptext = sr.ReadToEnd();
                            }
                        } catch { }
                        if(!string.IsNullOrEmpty(ptext)) {
                            try {
                                var pObj = Newtonsoft.Json.Linq.JObject.Parse(ptext);
                                var pPhase = (string)pObj["phase"];
                                if (!string.IsNullOrEmpty(pPhase)) {
                                    context.SetVarValue("installProgress",ptext);
                                    if (progressDispatcher != null && progressWin != null) {
                                        var pPctVal = (int?)pObj["percent"] ?? -1;
                                        var pDetailVal = (string)pObj["detail"] ?? pPhase ?? "正在准备…";
                                        progressDispatcher.BeginInvoke(new System.Action(() => {
                                            if (pPctVal >= 0) {
                                                pBar.IsIndeterminate = false;
                                                pBar.Value = System.Math.Max(0, System.Math.Min(100, pPctVal));
                                                pPct.Text = pPctVal + "%";
                                            } else {
                                                pBar.IsIndeterminate = true;
                                                pPct.Text = "";
                                            }
                                            pMsg.Text = pDetailVal;
                                        }));
                                    }
                                }
                            } catch (System.Exception parseEx) {
                                try { context.SetVarValue("diag:progressParseError", parseEx.Message); } catch { }
                            }
                        }
                    }
                }
                if (!windowShown && (System.DateTime.UtcNow - startTime).TotalMilliseconds >= 1200) {
                    if (!progressFinished && progressDispatcher != null && progressWin != null) {
                        progressDispatcher.BeginInvoke(new System.Action(() => {
                            if (progressFinished) return;
                            progressWin.Visibility = System.Windows.Visibility.Visible;
                            progressWin.Show();
                        }));
                        windowShown = true;
                    }
                }
            } catch {}
            if(System.DateTime.UtcNow>=deadline) {
                try{process.Kill();}catch{}
                var timeoutObj = new Newtonsoft.Json.Linq.JObject();
                timeoutObj["protocolVersion"] = 1;
                timeoutObj["productId"] = "PSFlowBridge";
                timeoutObj["operation"] = effectiveOp;
                if (!string.IsNullOrEmpty(requestId)) timeoutObj["requestId"] = requestId;
                timeoutObj["ok"] = false;
                timeoutObj["status"] = "failed";
                timeoutObj["error"] = "准备超时（已等待超过 600 秒），请先查询当前运行状态再重试。";
                var timeoutJson = timeoutObj.ToString(Newtonsoft.Json.Formatting.None);
                try { context.SetVarValue("installerResult", timeoutJson); } catch { }
                try { context.SetVarValue("response", timeoutJson); } catch { }
                throw new System.Exception((string)timeoutObj["error"]);
            }
        }
        try { if(System.IO.File.Exists(progressFile)) { var text=System.IO.File.ReadAllText(progressFile); if(!string.IsNullOrEmpty(text)) context.SetVarValue("installProgress",text); } } catch {}
        if(!System.IO.File.Exists(statusFile)) {
            var failObj = new Newtonsoft.Json.Linq.JObject();
            failObj["protocolVersion"] = 1;
            failObj["productId"] = "PSFlowBridge";
            failObj["operation"] = effectiveOp;
            if (!string.IsNullOrEmpty(requestId)) failObj["requestId"] = requestId;
            failObj["ok"] = false;
            failObj["status"] = "failed";
            failObj["error"] = "Installer process exited with code " + process.ExitCode + " without writing status file.";
            var failJson = failObj.ToString(Newtonsoft.Json.Formatting.None);
            try { context.SetVarValue("installerResult", failJson); } catch { }
            try { context.SetVarValue("response", failJson); } catch { }
            throw new System.Exception((string)failObj["error"]);
        }
        var result=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText(statusFile));
        var rawJson=result.ToString(Newtonsoft.Json.Formatting.None);
        try { context.SetVarValue("installerResult",rawJson); } catch { }
        try { context.SetVarValue("response",rawJson); } catch { }
        if(process.ExitCode!=0||(bool?)result["ok"]!=true)throw new System.Exception((string)result["error"]??"运行组件准备失败。");
        var isNonRunningOp=(operation=="inspect"||operation=="remove-components"||operation=="clear-cache"||operation=="remove-local"||operation=="uninstall-runtime"||operation=="delete-user-data");
        if(isNonRunningOp)return true;
        var root=(string)result["packageRoot"];var node=(string)result["nodePath"];
        if(string.IsNullOrEmpty(root)||string.IsNullOrEmpty(node)||!System.IO.File.Exists(System.IO.Path.Combine(root,"action-ui","panel.html"))||!System.IO.File.Exists(node))throw new System.Exception("运行位置无效，未打开面板。");
        context.WriteState("packageRoot",root);context.WriteState("nodePath",node);
        context.SetVarValue("root",root);
    }
} finally {
    context.SetVarValue("installDone",true);
    context.SetVarValue("installRunning",false);
    progressFinished = true;
    if (progressDispatcher != null) {
        try {
            progressDispatcher.BeginInvoke(new System.Action(() => {
                try {
                    if (progressWin != null) {
                        progressWin.Close();
                    }
                } catch { }
                try {
                    progressDispatcher.InvokeShutdown();
                } catch { }
            }));
        } catch {}
    }
    if (progressUiThread != null) {
        try {
            progressUiThread.Join(1500);
        } catch { }
    }
    try{if(System.IO.File.Exists(statusFile))System.IO.File.Delete(statusFile);}catch{}
    if(isProgressOwner){try{if(System.IO.File.Exists(progressFile))System.IO.File.Delete(progressFile);}catch{}}
}
return true;
